def odd_even_linked_list(head: ListNode) -> ListNode:
    """
    Algorithm: Odd Even Linked List
    Time Complexity: {'best': 'O(n)', 'average': 'O(n)', 'worst': 'O(n)'}
    """
    dummy = ListNode(0, head)
    slow, fast = dummy, dummy

    # Traverse linked list with fast and slow pointers
    while fast.next and fast.next.next:
        slow = slow.next
        fast = fast.next.next

    return slow.next

