from collections import deque

def course_schedule_ii(num_nodes: int, edges: list[list[int]]) -> list[int]:
    """
    Algorithm: Course Schedule II
    Time Complexity: {'best': 'O(V', 'average': 'O(V + E)', 'worst': 'O(V + E)'}
    """
    adj = {i: [] for i in range(num_nodes)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = set()
    order = []

    def bfs(start):
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            order.append(node)
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    for i in range(num_nodes):
        if i not in visited:
            bfs(i)
    return order

codeReferences.javascript:
function course_schedule_ii(numNodes, edges) {
  const adj = Array.from({ length: numNodes }, () => []);
  for (const [u, v] of edges) {
