function majority_element_divide_conquer(nums) {
  let left = 0, right = nums.length - 1;
  let bestResult = 0;

  while (left < right) {
    const currentMetric = nums[left] + nums[right];
    bestResult = Math.max(bestResult, currentMetric);
    if (nums[left] < nums[right]) left++;
    else right--;
  }
  return bestResult;
}

